$proposalStatuses = ['pending' => 'در انتظار پاسخ', 'accepted' => 'پذیرفته‌شده', 'rejected' => 'ردشده', 'withdrawn' => 'منصرف‌شده'];
?>
<section class="dashboard-content"><div class="dashboard-heading"><div class="eyebrow">فضای کاری شخصی</div><h1>سلام، <?= e($profile['display_name'] ?: 'فریلنسر عزیز') ?> 👋</h1><p class="muted">پروفایل حرفه‌ای خود را کامل کنید و پروژه‌ی مناسب را پیدا کنید.</p></div><?php if ($message = Session::flash('success')): ?><div class="alert success">✅ <?= e($message) ?></div><?php endif; ?><?php if ($message = Session::flash('error')): ?><div class="alert error">⚠️ <?= e($message) ?></div><?php endif; ?><div class="stats-grid"><article class="stat-card"><strong class="stat-value"><?= count($proposals) ?></strong><span class="stat-label">پیشنهاد فعال</span></article><article class="stat-card"><strong class="stat-value"><?= count($skills) ?></strong><span class="stat-label">مهارت ثبت‌شده</span></article><article class="stat-card"><strong class="stat-value"><?= count($jobs) ?></strong><span class="stat-label">پروژه باز</span></article></div><div class="dashboard-grid"><section class="dash-card" id="profile"><div class="card-title"><h2>پروفایل حرفه‌ای من</h2><span>اطلاعات عمومی</span></div><form method="post" action="<?= url('/dashboard/freelancer/profile') ?>"><?= csrf_field() ?><div class="form-row"><label>نام نمایشی<input name="display_name" value="<?= e($profile['display_name']) ?>" required></label><label>نام کاربری<input name="username" value="<?= e($profile['username']) ?>" placeholder="your-username" required></label></div><label>عنوان شغلی<input name="headline" value="<?= e($profile['headline']) ?>" placeholder="مثلاً طراح محصول"></label><label>درباره من<textarea name="bio" rows="4" placeholder="تخصص و تجربه خود را معرفی کنید..."><?= e($profile['bio']) ?></textarea></label><div class="form-row"><label>نرخ ساعتی<input type="number" name="hourly_rate" min="0" step="0.01" value="<?= e($profile['hourly_rate']) ?>" placeholder="دلار"></label><label>منطقه زمانی<input name="timezone" value="<?= e($profile['timezone']) ?>"></label></div><label>وضعیت همکاری<select name="availability"><option value="available" <?= $profile['availability'] === 'available' ? 'selected' : '' ?>>آماده همکاری</option><option value="busy" <?= $profile['availability'] === 'busy' ? 'selected' : '' ?>>مشغول</option><option value="unavailable" <?= $profile['availability'] === 'unavailable' ? 'selected' : '' ?>>فعلاً در دسترس نیستم</option></select></label><button class="button" type="submit">ذخیره پروفایل</button></form></section><section class="dash-card" id="skills"><div class="card-title"><h2>مهارت‌های من</h2><span><?= count($skills) ?> مهارت</span></div><div class="skill-list"><?php foreach ($skills as $skill): ?><span class="skill-tag"><?= e($skill['name']) ?><small><?= e($skillLevels[$skill['level']] ?? $skill['level']) ?></small></span><?php endforeach; ?><?php if (!$skills): ?><p class="muted">هنوز مهارتی اضافه نکرده‌اید.</p><?php endif; ?></div><form class="skill-form" method="post" action="<?= url('/dashboard/freelancer/skills') ?>"><?= csrf_field() ?><select name="skill_id" required><option value="">انتخاب مهارت</option><?php foreach ($availableSkills as $skill): ?><option value="<?= e($skill['id']) ?>"><?= e($skill['name']) ?></option><?php endforeach; ?></select><select name="level"><option value="beginner">مقدماتی</option><option value="intermediate" selected>متوسط</option><option value="advanced">پیشرفته</option><option value="expert">متخصص</option></select><button class="button" type="submit">افزودن</button></form></section></div><section class="dash-card jobs-card" id="jobs"><div class="card-title"><h2>پروژه‌های پیشنهادی برای شما</h2><span><?= count($jobs) ?> پروژه باز</span></div><?php foreach ($jobs as $job): ?><article class="job-item"><div class="job-info"><h3><?= e($job['title']) ?></h3><p><?= e(mb_strimwidth($job['description'], 0, 150, '…')) ?></p><small>کارفرما: <?= e($job['employer_name'] ?: 'کارفرما') ?> · بودجه: <?= e($job['budget_min'] ?: '—') ?> تا <?= e($job['budget_max'] ?: '—') ?> دلار</small></div><?php if ((int) $job['already_applied']): ?><span class="applied">پیشنهاد ارسال شده</span><?php else: ?><details><summary class="button button-small">ارسال پیشنهاد</summary><form class="proposal-form" method="post" action="<?= url('/dashboard/freelancer/proposals') ?>"><?= csrf_field() ?><input type="hidden" name="job_id" value="<?= e($job['id']) ?>"><label>مبلغ پیشنهادی<input type="number" name="bid_amount" min="1" step="0.01" required placeholder="دلار"></label><label>متن پیشنهاد<textarea name="cover_letter" rows="3" required placeholder="چرا برای این پروژه مناسب هستید؟"></textarea></label><button class="button" type="submit">ثبت پیشنهاد همکاری</button></form></details><?php endif; ?></article><?php endforeach; ?><?php if (!$jobs): ?><p class="empty-state">در حال حاضر پروژه‌ی بازی برای نمایش وجود ندارد.</p><?php endif; ?></section><section class="dash-card" id="proposals"><div class="card-title"><h2>پیشنهادهای ارسال‌شده</h2></div><?php foreach ($proposals as $proposal): ?><div class="proposal-row"><strong><?= e($proposal['title']) ?></strong><span><?= e($proposal['bid_amount']) ?> دلار · <?= e($proposalStatuses[$proposal['status']] ?? $proposal['status']) ?></span></div><?php endforeach; ?><?php if (!$proposals): ?><p class="muted">هنوز پیشنهادی ارسال نکرده‌اید.</p><?php endif; ?></section></section>
